#include <Snooker/Rules/Migration.h>
#include <sstream>
namespace Snooker
{
namespace{bool Fail(std::string*e,const char*m){if(e)*e=m;return false;}std::string First(const std::string&t){std::istringstream s(t);std::string v;s>>v;return v;}}
bool MigrationReport::IsValid(std::string* Error)const{if(Kind.empty()||FromVersion.empty()||ToVersion.empty()||Message.empty())return Fail(Error,"invalid migration report");return true;}
bool MigrateMatchText(const std::string&t,MatchState&out,MigrationReport&r,std::string*e){const auto v=First(t);MigrationReport report;report.Kind="match";report.FromVersion=v;report.ToVersion="snooker-match-v2";if(v=="snooker-match-v3"||v.rfind("snooker-match-v",0)==0&&v!="snooker-match-v1"&&v!="snooker-match-v2"){report.Status=MigrationStatus::UnsupportedFuture;report.Message="unsupported future match schema";r=report;return false;}MatchState x;if(!MatchState::Deserialize(t,x,e)){report.Status=MigrationStatus::Invalid;report.Message="invalid match state";r=report;return false;}report.Status=v=="snooker-match-v1"?MigrationStatus::Migrated:MigrationStatus::Current;report.Message=report.Status==MigrationStatus::Migrated?"match-v1 migrated with default v2 fields":"match schema current";out=x;r=report;return true;}
bool MigrateSnapshotText(const std::string&t,PhysicsSnapshot&out,MigrationReport&r,std::string*e){const auto v=First(t);MigrationReport report{MigrationStatus::Invalid,"snapshot",v,"3","invalid snapshot"};if(v!="2"&&v!="3"){report.Status=MigrationStatus::UnsupportedFuture;report.Message="unsupported snapshot schema";r=report;return false;}PhysicsSnapshot x;if(!PhysicsSnapshot::Deserialize(t,x,e)){r=report;return false;}report.Status=v=="2"?MigrationStatus::Migrated:MigrationStatus::Current;report.Message=v=="2"?"snapshot-v2 migrated with OnCloth pocket states/event cursor zero":"snapshot schema current";out=x;r=report;return true;}
bool InspectShotText(const std::string&t,PhysicsShotRecord*out,MigrationReport&r,std::string*e){const auto v=First(t);MigrationReport report;report.Kind="shot";report.FromVersion=v;report.ToVersion="snooker-shot-v2";if(v=="snooker-shot-v1"){report.Status=MigrationStatus::RecognizedIncompatible;report.Message="legacy shot-v1 lacks the complete PhysicsBundle and cannot be physically replayed";r=report;return false;}if(v!="snooker-shot-v2"){report.Status=MigrationStatus::UnsupportedFuture;report.Message="unsupported shot schema";r=report;return false;}PhysicsShotRecord x;if(!PhysicsShotRecord::Deserialize(t,x,e)){report.Status=MigrationStatus::Invalid;report.Message="invalid shot-v2";r=report;return false;}report.Status=MigrationStatus::Current;report.Message="shot schema current";if(out)*out=x;r=report;return true;}
bool InspectFrameText(const std::string&t,FrameSave*out,MigrationReport&r,std::string*e){const auto v=First(t);MigrationReport report{MigrationStatus::Invalid,"frame",v,"snooker-frame-v1","invalid frame save"};if(v!="snooker-frame-v1"){report.Status=MigrationStatus::UnsupportedFuture;report.Message="unsupported frame schema";r=report;return false;}FrameSave x;if(!FrameSave::Deserialize(t,x,e)){r=report;return false;}report.Status=MigrationStatus::Current;report.Message="frame schema current";if(out)*out=x;r=report;return true;}
}
